// Get returns a task the actor may see.
func (s *TaskService) Get(ctx context.Context, actor domain.User, id int64) (domain.Task, error) {
	t, _, err := s.load(ctx, actor, id)
	return t, err
}

// load reads a task and what actor may do in its project. A task the actor may not
// see is reported exactly like a task that does not exist.
func (s *TaskService) load(ctx context.Context, actor domain.User, id int64) (domain.Task, access, error) {
	t, err := s.st.Tasks.Get(ctx, id)
	if err != nil {
		return domain.Task{}, access{}, err
	}
	a, err := accessTo(ctx, s.st.Projects, actor, t.ProjectID)
	if err != nil {
		return domain.Task{}, access{}, err
	}
	if !canView(a) {
		return domain.Task{}, access{}, notFound("task", id)
	}
	return t, a, nil
}

// TaskRepo is the PostgreSQL TaskStore.
type TaskRepo struct{ s *Store }

// NewTaskRepo returns the task repository of s.
func NewTaskRepo(s *Store) *TaskRepo { return &TaskRepo{s: s} }

// Get returns one task.
func (r *TaskRepo) Get(ctx context.Context, id int64) (domain.Task, error) {
	row, err := r.s.queries(ctx).GetTask(ctx, id)
	if err != nil {
		return domain.Task{}, mapError(err, "task", id)
	}
	return toDomainTask(row)
}

// TaskStore keeps tasks. Like every store here, its methods run inside the
// transaction that ctx carries when they are called from TxRunner.InTx.
type TaskStore interface {
	Get(ctx context.Context, id int64) (domain.Task, error)
	// List returns one page of tasks and how many tasks match the filter in all.
	List(ctx context.Context, f domain.TaskFilter) ([]domain.Task, int64, error)
	CountByStatus(ctx context.Context, projectID int64) (domain.TaskCounts, error)
	Create(ctx context.Context, t domain.Task) (domain.Task, error)
	// Update saves t's fields if the stored task is still at t.Version, and returns it
	// at the next version. A stale version gives a *domain.StaleTaskError.
	Update(ctx context.Context, t domain.Task) (domain.Task, error)
	// Transition saves t's Status and CompletedAt, with the same version check.
	Transition(ctx context.Context, t domain.Task) (domain.Task, error)
	Delete(ctx context.Context, id int64) error
}
